const ALLOWED_REDIRECTS = ['/dashboard', '/profile', '/settings'];

app.get('/redirect', (req, res) => {
  const next = req.query.next;
  if (ALLOWED_REDIRECTS.includes(next)) {
    res.redirect(next);
  } else {
    res.redirect('/dashboard');
  }
});

